import{_ as i,I as e,o as n,c as d,b6 as t,J as h}from"./chunks/framework.COUcLbTA.js";const u=JSON.parse('{"title":"SSH 与密钥认证","description":"","frontmatter":{},"headers":[],"relativePath":"zh-cn/appendix/2-development-tools/ssh-authentication.md","filePath":"zh-cn/appendix/2-development-tools/ssh-authentication.md"}'),l={name:"zh-cn/appendix/2-development-tools/ssh-authentication.md"};function r(o,s,p,c,k,g){const a=e("SSHAuthDemo");return n(),d("div",null,[s[0]||(s[0]=t('<h1 id="ssh-与密钥认证" tabindex="-1">SSH 与密钥认证 <a class="header-anchor" href="#ssh-与密钥认证" aria-label="Permalink to “SSH 与密钥认证”">​</a></h1><blockquote><p>💡 <strong>学习指南</strong>：每次 <code>git push</code> 输密码？连服务器总被提示&quot;Permission denied&quot;？本章用 5 分钟带你搞懂 SSH 密钥认证的原理，以及如何一键免密登录 GitHub 和服务器。</p></blockquote><hr><h2 id="_0-你一定遇到过这些场景" tabindex="-1">0. 你一定遇到过这些场景 <a class="header-anchor" href="#_0-你一定遇到过这些场景" aria-label="Permalink to “0. 你一定遇到过这些场景”">​</a></h2><ul><li><code>git push</code> 时反复弹出密码输入框，烦不胜烦</li><li>SSH 连接服务器失败，不知道 <code>id_rsa</code> 和 <code>id_ed25519</code> 是什么</li><li>听说&quot;公钥&quot;和&quot;私钥&quot;，但搞不清哪个给别人、哪个自己留</li></ul><p><strong>核心矛盾</strong>：密码不安全、又麻烦。SSH 密钥就是用来同时解决安全性和便利性的方案。</p><hr><h2 id="_1-密码-vs-密钥-为什么密钥更好" tabindex="-1">1. 密码 vs 密钥：为什么密钥更好？ <a class="header-anchor" href="#_1-密码-vs-密钥-为什么密钥更好" aria-label="Permalink to “1. 密码 vs 密钥：为什么密钥更好？”">​</a></h2><p>👇 动手点点看：对比密码登录和密钥登录的区别</p>',9)),h(a),s[1]||(s[1]=t(`<div class="tip custom-block"><p class="custom-block-title">💡 一句话总结</p><p>密码登录 = 每次把密码发过去让对方核对（密码可能被截获）；<br> 密钥登录 = 证明&quot;我有钥匙&quot;但不用把钥匙给你看（私钥永不传输）。</p></div><hr><h2 id="_2-非对称加密-公钥和私钥" tabindex="-1">2. 非对称加密：公钥和私钥 <a class="header-anchor" href="#_2-非对称加密-公钥和私钥" aria-label="Permalink to “2. 非对称加密：公钥和私钥”">​</a></h2><p>SSH 密钥基于<strong>非对称加密</strong>，一次生成两把钥匙：</p><table tabindex="0"><thead><tr><th></th><th>私钥 (Private Key)</th><th>公钥 (Public Key)</th></tr></thead><tbody><tr><td><strong>保存位置</strong></td><td>你的电脑 <code>~/.ssh/id_ed25519</code></td><td>服务器/GitHub</td></tr><tr><td><strong>可以给别人吗</strong></td><td>❌ 绝不</td><td>✅ 随便给</td></tr><tr><td><strong>功能</strong></td><td>签名（证明身份）</td><td>验签（验证身份）</td></tr><tr><td><strong>类比</strong></td><td>钥匙</td><td>锁</td></tr></tbody></table><h3 id="常见密钥类型" tabindex="-1">常见密钥类型 <a class="header-anchor" href="#常见密钥类型" aria-label="Permalink to “常见密钥类型”">​</a></h3><table tabindex="0"><thead><tr><th>类型</th><th>命令</th><th>推荐度</th><th>说明</th></tr></thead><tbody><tr><td><strong>Ed25519</strong></td><td><code>ssh-keygen -t ed25519</code></td><td>⭐⭐⭐</td><td>最新最快最安全</td></tr><tr><td><strong>RSA</strong></td><td><code>ssh-keygen -t rsa -b 4096</code></td><td>⭐⭐</td><td>兼容性好，但较慢</td></tr><tr><td><strong>ECDSA</strong></td><td><code>ssh-keygen -t ecdsa</code></td><td>⭐</td><td>一般不推荐</td></tr></tbody></table><hr><h2 id="_3-实战-生成并配置-ssh-密钥" tabindex="-1">3. 实战：生成并配置 SSH 密钥 <a class="header-anchor" href="#_3-实战-生成并配置-ssh-密钥" aria-label="Permalink to “3. 实战：生成并配置 SSH 密钥”">​</a></h2><h3 id="_3-1-生成密钥对" tabindex="-1">3.1 生成密钥对 <a class="header-anchor" href="#_3-1-生成密钥对" aria-label="Permalink to “3.1 生成密钥对”">​</a></h3><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ssh-keygen</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ed25519</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -C</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;your@email.com&quot;</span></span></code></pre></div><p>执行后会提示：</p><ul><li><strong>文件路径</strong>：直接回车用默认路径 <code>~/.ssh/id_ed25519</code></li><li><strong>密码短语</strong>：可以设置额外保护（也可留空）</li></ul><h3 id="_3-2-把公钥添加到-github" tabindex="-1">3.2 把公钥添加到 GitHub <a class="header-anchor" href="#_3-2-把公钥添加到-github" aria-label="Permalink to “3.2 把公钥添加到 GitHub”">​</a></h3><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 1. 复制公钥内容</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.ssh/id_ed25519.pub</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> pbcopy</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # macOS</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.ssh/id_ed25519.pub</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> xclip</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # Linux</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 2. 打开 GitHub → Settings → SSH and GPG keys → New SSH key</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 3. 粘贴公钥，保存</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 4. 测试连接</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ssh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -T</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> git@github.com</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 成功会看到: Hi username! You&#39;ve been authenticated...</span></span></code></pre></div><h3 id="_3-3-把公钥添加到服务器" tabindex="-1">3.3 把公钥添加到服务器 <a class="header-anchor" href="#_3-3-把公钥添加到服务器" aria-label="Permalink to “3.3 把公钥添加到服务器”">​</a></h3><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 方式一：ssh-copy-id（推荐）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ssh-copy-id</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> user@your-server</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 方式二：手动复制</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.ssh/id_ed25519.pub</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> ssh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> user@server</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;mkdir -p ~/.ssh &amp;&amp; cat &gt;&gt; ~/.ssh/authorized_keys&quot;</span></span></code></pre></div><hr><h2 id="_4-ssh-config-告别长命令" tabindex="-1">4. SSH Config：告别长命令 <a class="header-anchor" href="#_4-ssh-config-告别长命令" aria-label="Permalink to “4. SSH Config：告别长命令”">​</a></h2><p>在 <code>~/.ssh/config</code> 中配置别名，一次配置终身受益：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Host dev</span></span>
<span class="line"><span>  HostName 192.168.1.100</span></span>
<span class="line"><span>  User deploy</span></span>
<span class="line"><span>  IdentityFile ~/.ssh/id_ed25519</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Host github.com</span></span>
<span class="line"><span>  HostName github.com</span></span>
<span class="line"><span>  User git</span></span>
<span class="line"><span>  IdentityFile ~/.ssh/id_ed25519</span></span></code></pre></div><p>配置后的效果：</p><table tabindex="0"><thead><tr><th>之前</th><th>之后</th></tr></thead><tbody><tr><td><code>ssh -i ~/.ssh/id_ed25519 deploy@192.168.1.100</code></td><td><code>ssh dev</code></td></tr><tr><td>每次都要记 IP 和用户名</td><td>记一个别名就够</td></tr></tbody></table><hr><h2 id="_5-常见问题排查" tabindex="-1">5. 常见问题排查 <a class="header-anchor" href="#_5-常见问题排查" aria-label="Permalink to “5. 常见问题排查”">​</a></h2><table tabindex="0"><thead><tr><th>问题</th><th>原因</th><th>解决方案</th></tr></thead><tbody><tr><td><code>Permission denied (publickey)</code></td><td>公钥没添加到服务器</td><td><code>ssh-copy-id user@server</code></td></tr><tr><td><code>WARNING: UNPROTECTED PRIVATE KEY FILE</code></td><td>私钥文件权限太宽</td><td><code>chmod 600 ~/.ssh/id_ed25519</code></td></tr><tr><td><code>Could not resolve hostname</code></td><td>SSH Config 配置有误</td><td>检查 <code>~/.ssh/config</code> 格式</td></tr><tr><td>GitHub 还是要密码</td><td>用的 HTTPS 而非 SSH</td><td>改用 <code>git@github.com:user/repo.git</code></td></tr></tbody></table><hr><h2 id="_6-总结" tabindex="-1">6. 总结 <a class="header-anchor" href="#_6-总结" aria-label="Permalink to “6. 总结”">​</a></h2><div class="tip custom-block"><p class="custom-block-title">📚 核心要点</p><ol><li><strong>密钥 &gt; 密码</strong>：私钥永不传输，比密码安全得多</li><li><strong>推荐 Ed25519</strong>：最现代的密钥算法，速度快、安全性高</li><li><strong>公钥随便给，私钥绝不泄露</strong>：记住这条铁律</li><li><strong>SSH Config</strong>：配一次别名，之后 <code>ssh 别名</code> 一键连接</li><li><strong>GitHub/GitLab</strong>：添加公钥后，<code>git push/pull</code> 再也不需要输密码</li></ol></div><p><strong>下一步学习</strong>：</p><ul><li><a href="./ports-localhost.html">端口与 localhost</a> - 理解网络连接的基础</li><li><a href="./environment-path.html">环境变量与 PATH</a> - 理解系统配置</li></ul>`,31))])}const y=i(l,[["render",r]]);export{u as __pageData,y as default};
